import json

class MessagePayload:
    def __init__(self, event_data: dict):
        self.event_data = event_data

    def to_json(self):
        return json.dumps(self.event_data)

    @classmethod
    def from_json(cls, json_string: str):
        return cls(json.loads(json_string))

class MessageResponse:
    def __init__(self, message_id: str, status: str = "SUCCESS", details: dict = None):
        self.message_id = message_id
        self.status = status
        self.details = details or {}

    def to_dict(self):
        return {"message_id": self.message_id, "status": self.status, "details": self.details}

import json
import os

from messaging_client import get_sqs_client

def send_to_dead_letter_queue(original_message_body: dict, dead_letter_queue_url: str, region_name: str = None):
    sqs_client = get_sqs_client(region_name)

    # The message body should contain enough information to understand what failed
    # For this example, we'll stringify the original message body
    message_body_str = json.dumps(original_message_body)

    response = sqs_client.send_message(
        QueueUrl=dead_letter_queue_url,
        MessageBody=message_body_str,
        MessageAttributes={
            'FailureReason': {
                'StringValue': 'Message processing failed',
                'DataType': 'String'
            }
        }
    )
    return {"status": "Sent to dead-letter queue", "message_id": response["MessageId"]}

import json
import os

from messaging_client import get_sns_client

def batch_publish(messages: list[dict], topic_arn: str = None, region_name: str = None):
    sns_client = get_sns_client(region_name)
    topic_arn = topic_arn or os.environ.get("SNS_TOPIC_ARN")
    if not topic_arn:
        raise ValueError("SNS Topic ARN must be provided or set in environment variables.")

    # Each message in the batch must have a 'Id' and 'MessageBody'
    # 'MessageBody' is the actual content, which we expect to be a JSON string
    entries = [
        {
            'Id': msg.get("Id") or str(idx),
            'Message': json.dumps(msg["Message"]),
            'MessageAttributes': msg.get("MessageAttributes", {})
        }
        for idx, msg in enumerate(messages)
    ]

    response = sns_client.publish_batch(
        TopicArn=topic_arn,
        PublishBatchRequestEntries=entries
    )
    return {
        "successful": response.get("Successful", []),
        "failed": response.get("Failed", [])
    }

import json
import os
import datetime

from messaging_client import get_dynamodb_client

def persist_message_record(message_id: str, payload: dict, processing_status: str, table_name: str = None, region_name: str = None):
    dynamodb_client = get_dynamodb_client(region_name)
    table_name = table_name or os.environ.get("DYNAMODB_AUDIT_TABLE_NAME")
    if not table_name:
        raise ValueError("DynamoDB table name must be provided or set in environment variables.")

    timestamp = datetime.datetime.utcnow().isoformat()

    item = {
        'message_id': {'S': message_id},
        'timestamp': {'S': timestamp},
        'payload': {'S': json.dumps(payload)},
        'processing_status': {'S': processing_status}
    }

    response = dynamodb_client.put_item(
        TableName=table_name,
        Item=item
    )

    return {"status": "Message record persisted", "message_id": message_id, "dynamodb_response_metadata": response["ResponseMetadata"]}
